"""Build a public evidence report and a local edition with the 200 reference captures."""
from pathlib import Path
import json,shutil,html
ROOT=Path(__file__).resolve().parents[2]
PUBLIC=ROOT/'outputs/domestic-test/junction-report'
LOCAL=ROOT/'work/junction-report/local'
SURVEY=ROOT/'work/road-junction-survey-20261122'
EVIDENCE=ROOT/'verification/junction-generation'
esc=lambda s:html.escape(str(s),quote=True)
photos=json.loads((SURVEY/'manifest.json').read_text())
groups=json.loads((SURVEY/'groups.json').read_text())
photo_by={p['id']:p for p in photos}
images={
 'overview.jpg':EVIDENCE/'public-ramp-fixed-top.jpg',
 'left.jpg':EVIDENCE/'public-ramp-fixed-eye-left.jpg',
 'right.jpg':EVIDENCE/'public-ramp-fixed-eye-right.jpg',
 'walk.jpg':EVIDENCE/'public-ramp-fixed-sidewalk-walk.jpg',
 'before-ramp.jpg':EVIDENCE/'public-final-crossing-eye.jpg',
 'before-seam.jpg':EVIDENCE/'public-width-fixed-top.png',
 'bus-before.jpg':EVIDENCE/'local-dobong-top.png',
 'bus-after.jpg':EVIDENCE/'local-dobong-fixed.png',
 'grade-matrix.png':EVIDENCE/'grade-pairs.png',
 'asset-alley.jpg':ROOT/'verification/junction-assets/public-alley-main.jpg',
 'asset-t.jpg':ROOT/'verification/junction-assets/public-small-t.jpg',
 'asset-cross.jpg':ROOT/'verification/junction-assets/public-crossroads.jpg',
}
css='''
:root{color-scheme:light;--ink:#183c3b;--muted:#526968;--paper:#f5f5ed;--white:#fff;--line:#d4ded6;--accent:#23685d;--warm:#edc677;--space:1.25rem;--radius:1rem}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:5rem}body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,"Apple SD Gothic Neo","Malgun Gothic",sans-serif;line-height:1.75}a{color:var(--accent);text-underline-offset:.25em}a:hover{text-decoration-thickness:.15em}a:focus-visible,summary:focus-visible{outline:.2rem solid var(--accent);outline-offset:.3rem}.skip{position:absolute;left:1rem;top:-6rem;z-index:9}.skip:focus{top:1rem;background:white;padding:1rem}.top{position:sticky;top:0;z-index:3;border-bottom:1px solid var(--line);background:#f5f5edf5;backdrop-filter:blur(12px)}.nav{max-width:1280px;margin:auto;display:flex;gap:1.5rem;align-items:center;padding:.8rem 1.5rem;overflow:auto;white-space:nowrap}.brand{font-weight:800;margin-right:auto;text-decoration:none}.nav a{font-size:.85rem}main{max-width:1280px;margin:auto;padding:3.5rem 1.5rem 5rem}.eyebrow{font-size:.8rem;font-weight:750;letter-spacing:.1em;text-transform:uppercase;color:var(--accent)}h1{font-size:clamp(2.6rem,5vw,4.6rem);letter-spacing:-.055em;line-height:1.15;margin:.8rem 0 1.3rem;max-width:15ch}h2{font-size:clamp(1.7rem,3vw,2.5rem);letter-spacing:-.04em;line-height:1.3;margin:.4rem 0 1rem}h3{font-size:1.1rem;margin:.6rem 0}p{margin:.6rem 0 1rem}.lead{font-size:1.12rem;color:var(--muted);max-width:56ch}.hero{display:grid;grid-template-columns:1fr 1fr;gap:3rem;align-items:center}.hero figure{margin:0}.hero img{max-height:630px;object-fit:contain;background:#dde5df}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;margin:2rem 0}.stat{background:var(--white);padding:1.2rem}.stat strong{display:block;font-size:2rem;line-height:1.3}.stat small{color:var(--muted)}section{padding-top:4rem;margin-top:1.5rem;border-top:1px solid var(--line)}.section-intro{max-width:70ch;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.25rem}.grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}.card,figure{margin:0;background:var(--white);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}.card{padding:1.5rem}.card figure{margin:1rem 0}.media{display:block;background:#e5eae5}.media img{display:block;width:100%;height:auto}.media:focus-visible{outline-offset:-.3rem}figcaption{padding:1rem 1.2rem;font-size:.9rem;color:var(--muted)}figcaption strong{display:block;color:var(--ink);font-size:1rem}.tag{display:inline-block;font-size:.75rem;font-weight:700;border:1px solid var(--line);border-radius:2rem;padding:.1rem .6rem;margin-bottom:.4rem}.tag.good{background:#e4eee7;color:#185546}.tag.old{background:#fbefdc;color:#78501d}.note{border-left:.25rem solid var(--accent);padding:1rem 1.3rem;background:#e9eee8;margin:1.4rem 0}.warning{border-left-color:#9a6727;background:#fbf0dd}.rules{counter-reset:rule}.rule{position:relative;padding:1.6rem 1.6rem 1.6rem 4rem;counter-increment:rule}.rule:before{content:counter(rule,decimal-leading-zero);position:absolute;left:1.3rem;top:1.7rem;font-weight:800;color:var(--accent)}.ref-placeholder{padding:2rem 1.5rem;background:#edf0e9;min-height:15rem;display:flex;flex-direction:column;justify-content:center}.ref-placeholder b{font-size:2rem}.caption-note{font-size:.85rem;color:var(--muted)}details{background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:1rem 1.25rem;margin:.9rem 0}summary{cursor:pointer;font-weight:700}details .grid{margin-top:1rem}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:var(--radius)}table{width:100%;border-collapse:collapse;background:white;font-size:.9rem;min-width:580px}th,td{text-align:left;padding:1rem;border-bottom:1px solid var(--line);vertical-align:top}th{background:#e9eee8}tbody tr:last-child td{border:0}.links{display:flex;flex-wrap:wrap;gap:.7rem 1.5rem}.button{display:inline-block;padding:.7rem 1rem;border:1px solid var(--accent);border-radius:.5rem;text-decoration:none;font-weight:700;background:var(--accent);color:white}.button.secondary{color:var(--accent);background:transparent}footer{border-top:1px solid var(--line);margin-top:4rem;padding-top:1.5rem;color:var(--muted);font-size:.85rem}code{overflow-wrap:anywhere}ul{padding-left:1.2rem}.reference-grid img{aspect-ratio:5/6;object-fit:contain;background:#e4e8e3}.archive img{aspect-ratio:5/6;object-fit:contain}.archive figure{font-size:.8rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;font-size:.85rem;line-height:1.8} @media(max-width:760px){main{padding:2rem 1rem}.hero,.grid,.grid.three{grid-template-columns:1fr}.hero{gap:1.5rem}.hero img{max-height:580px}.stats{grid-template-columns:repeat(2,1fr)}.nav{padding:.7rem 1rem;gap:1rem}.brand{margin-right:1rem}.archive{grid-template-columns:repeat(2,minmax(0,1fr))}.archive figcaption{padding:.6rem}.card{padding:1rem}section{padding-top:2.5rem}h1{max-width:none}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{.top,.skip,.button{display:none}main{max-width:none;padding:0}body{background:white}section{break-before:auto}.card,figure{break-inside:avoid}details{display:block}}
'''
def figure(src,title,desc,first=False):
 return f'<figure><a class="media" href="{esc(src)}" target="_blank" rel="noopener" aria-label="{esc(title)} 원본 크게 보기"><img src="{esc(src)}" alt="{esc(title)}" {"fetchpriority=high" if first else "loading=lazy"} decoding="async"></a><figcaption><strong>{esc(title)}</strong>{esc(desc)}</figcaption></figure>'
def reference(id,local):
 p=photo_by[id];g=next(g for g in groups if g['group']==p['group'])
 media=f'<a class="media" href="photos/{id}.jpg" target="_blank" rel="noopener"><img src="photos/{id}.jpg" alt="{esc(p["label"])}" loading="lazy" decoding="async"></a>' if local else f'<div class="ref-placeholder"><span class="eyebrow">참고 사진</span><b>#{id}</b><span>원본은 사진 첨부판에 보관</span><a href="{esc(p["sourceSearchUrl"])}" target="_blank" rel="noopener">카카오맵에서 이 일대 보기 ↗</a></div>'
 return f'<figure>{media}<figcaption><strong>#{id} · {esc(g["location"])}</strong>{esc(g["observed"])}<br><span class="caption-note">카카오맵 로드뷰 · 영상 {esc(p["imageryDate"])} · {esc(p["viewMeaning"])}</span></figcaption></figure>'
def build(local):
 out=LOCAL if local else PUBLIC;out.mkdir(parents=True,exist_ok=True);(out/'images').mkdir(exist_ok=True);(out/'documents').mkdir(exist_ok=True)
 for name,source in images.items():shutil.copyfile(source,out/'images'/name)
 for name,source in {'independent-review.txt':ROOT/'work/junction-generation-review/report.txt','final-review.txt':ROOT/'work/junction-generation-review/root-review.txt','completion.json':EVIDENCE/'completion.json','guideline-addendum.txt':ROOT/'work/junction-generation/guideline-addendum.txt'}.items():shutil.copyfile(source,out/'documents'/name)
 (out/'style.css').write_text(css)
 if local:
  (out/'photos').mkdir(exist_ok=True)
  for p in photos:shutil.copyfile(SURVEY/p['file'],out/'photos'/f"{p['id']}.jpg")
 mode='사진 200장 첨부판 · 이 컴퓨터에서 열기' if local else '공개판 · 실제 배치 화면과 검토 결과'
 notices='참고 로드뷰 200장과 실제 생성 화면을 모두 첨부했습니다. 이미지를 누르면 원본을 크게 볼 수 있습니다.' if local else '참고 로드뷰 원본은 사용 조건이 확인되지 않아 공개 서버에 올리지 않았습니다. 아래에는 관찰 내용과 원본 지도 링크를 표시합니다. 이 컴퓨터의 사진 첨부판에는 200장을 모두 넣었습니다.'
 body=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="우리동네 교차로 자동 생성 최종 검토. 참고 사진, 실제 배치, 수정 전후와 확인 범위를 비교합니다."><title>교차로가 동네에 놓이기까지 · 우리동네 검토 보고서</title><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#main">본문으로 이동</a><header class="top"><nav class="nav" aria-label="보고서 목차"><a class="brand" href="#main">우리동네 / 검토 기록</a><a href="#placed">실제 배치</a><a href="#reference">사진과 규칙</a><a href="#changes">수정 전후</a><a href="#assets">부품</a><a href="#limits">남은 문제</a><a href="#archive">사진 목록</a></nav></header><main id="main">
<div class="hero"><div><p class="eyebrow">Junction field report · 2026.11.22</p><h1>길이 만나는 곳,<br>자연스럽게 잇기.</h1><p class="lead">사진에서 정한 규칙을 실제 동네 생성에 적용하고, 눈높이에서 다시 확인했습니다. 도로 연결부터 횡단보도, 경사판과 점자블록까지의 최종 검토입니다.</p><span class="tag good">공개 배치 확인</span> <span class="tag">{mode}</span><p class="caption-note">검사 기준 소스 7a0323e · 검사 사본 87956683bb5545f2<br>2026년 11월 22일 확인 기록입니다. 이후 버전 전체에 대한 재검사 기록은 아닙니다.</p><div class="links"><a class="button" href="#placed">실제 배치 화면 보기</a><a class="button secondary" href="#changes">무엇을 고쳤는지 보기</a></div></div>{figure('images/right.jpg','실제 배치 · 횡단부 눈높이','공개 동네에서 전체 재생성한 결과. 차도와 경사판이 이어지고, 점자블록은 횡단 방향에 직각으로 놓입니다.',True)}</div>
<div class="stats"><div class="stat"><strong>5곳</strong><small>실제 생성 교차로</small></div><div class="stat"><strong>2곳</strong><small>자동 배치 횡단보도</small></div><div class="stat"><strong>4 + 4</strong><small>경사판 · 점자블록</small></div><div class="stat"><strong>200장</strong><small>참고 사진 · 25개 관찰 묶음</small></div></div>
<p class="note">{notices}</p>
<section id="placed"><p class="eyebrow">01 / 실제 동네</p><h2>예시 조립이 아닌, 지도에서 만든 결과</h2><p class="section-intro">도봉로198 일대의 저장된 실제 원자료를 공개 사이트에서 전체 재생성했습니다. 원본 동네는 보존하고 검사 사본에서 확인했습니다. 참고 사진과 이 생성 장면은 같은 촬영 위치를 그대로 재현한 전후 사진이 아닙니다.</p><div class="grid">{figure('images/overview.jpg','위에서 본 연결','1–2차, 1–3차, 2–3차 도로 조합을 실제 장면에서 확인했습니다. 도로 패치의 검은 원호선이 사라졌습니다.')}{figure('images/walk.jpg','경사판에서 옆 보도로','공개 화면에서 경사판 상단에 진입한 뒤 옆 보도로 약 4.12m 걸었습니다. 보도면 폭과 실제 장애물을 뺀 통로폭은 구분합니다.')}{figure('images/left.jpg','횡단부 왼쪽 · 수정 후','앞을 막던 약 15cm 단차가 사라졌습니다. 경사판과 점자블록을 실제 노면에 맞췄습니다.')}{figure('images/right.jpg','횡단부 오른쪽 · 수정 후','경고띠의 긴 방향을 횡단 진행 방향과 직각으로 바꿨습니다. 가까운 담장 옆 보도 연결도 확인했습니다.')}</div></section>
<section id="reference"><p class="eyebrow">02 / 관찰 → 규칙</p><h2>사진에서 가져온 것, 그대로 복제하지 않은 것</h2><p class="section-intro">사진 200장은 200개의 서로 다른 교차로가 아닙니다. 같은 일대에서 시점을 돌려 기록한 사진이 포함됩니다. 영상 표시는 2026년 6월이며, 정확한 파노라마 ID와 방위각은 수집하지 않았습니다.</p><div class="grid reference-grid">'''
 cases=[('017','보도 유무를 먼저 확인','좁아 보여도 양쪽 보도가 있으면 1차도로로 단정하지 않습니다. 처음의 1–4차 확정 분류를 철회했습니다.'),('059','별도 경사 통로는 구분','밝고 거친 포장의 경사 통로를 일반 아스팔트 차량 골목으로 취급하지 않습니다.'),('105','보행 입구는 비워 두기','사진에는 점자블록 위 기둥이 보입니다. 실제의 장애물을 좋은 생성 규칙으로 복제하지 않고 횡단부 접근 공간을 확보합니다.'),('121','분리대가 만드는 연결 제한','골목 정면의 분리대 연속 여부는 가림 때문에 확정하지 않았습니다. 분리대가 없다고 회전이 허용되는 것으로 추정하지 않습니다.'),('145','차선은 역할에 맞춰 연결','교차로 내부 유도선과 접근부 중앙선·정지선·횡단보도를 구분합니다. 가능한 모든 회전에 유도선을 자동으로 긋지 않습니다.'),('185','기존 전용차로 표시 보존','기존 청색 차선과 분리시설을 먼저 보존하고, 새 흰선·노란선이 겹치지 않도록 합니다.')]
 for id,title,desc in cases:body+=f'<article class="card"><span class="tag">관찰 사진 #{id}</span><h3>{title}</h3><p>{desc}</p>{reference(id,local)}</article>'
 body+='</div></section>'
 body+=f'''<section id="changes"><p class="eyebrow">03 / 검토에서 찾은 결함</p><h2>수치 통과 뒤에도, 눈높이에서 다시 고쳤습니다</h2><h3>경사판 누락 · 약 15cm 단차</h3><p>경계의 아주 작은 오차 때문에 승인된 경사판 4개 중 2개가 빠졌습니다. 계획 개수와 실제 생성 개수를 분리하고, 같은 확정 면으로 보도 제거와 경사판을 만들도록 고쳤습니다.</p><div class="grid">{figure('images/before-ramp.jpg','수정 전 · 경사판이 빠진 입구','이전 공개 소스 73aee99. 횡단보도 끝에 높은 면이 남았습니다. 최신 완료 화면이 아닙니다.')}{figure('images/left.jpg','수정 후 · 열린 입구','공개 소스 7a0323e. 동일 횡단부를 다시 확인했습니다. 시점은 완전히 동일하지 않습니다.')}</div><h3>교차부 접합 · 검은 원호선</h3><div class="grid">{figure('images/before-seam.jpg','수정 전 · 패치 경계가 드러남','이전 공개 도로폭 수정 단계. 객체 외곽선과 실제 높이 차를 나눠 조사했습니다.')}{figure('images/overview.jpg','수정 후 · 연속된 노면','기존 삼각면의 경계 높이를 공유하고, 같은 아스팔트 면을 하나로 연결했습니다.')}</div><details><summary>청색 전용차로 표시의 수정 전후 보기 · 실제 자료의 로컬 검사</summary><p>아래 두 화면은 같은 카메라의 로컬 재적용 비교입니다. 위의 공개 도봉로198 장면과 다른 검사이며 공개 화면 증거로 바꾸어 설명하지 않습니다.</p><div class="grid">{figure('images/bus-before.jpg','로컬 수정 전','새 교차로 패치에서 기존 청색 표시가 사라진 상태.')}{figure('images/bus-after.jpg','로컬 수정 후','기존 청색 표시를 보존하고 최종 노면 높이에 맞춰 연결한 상태.')}</div></details></section>
<section id="assets"><p class="eyebrow">04 / 부품과 자동 배치</p><h2>완성 교차로를 늘여 붙이지 않습니다</h2><p class="section-intro">백과에는 부품 9종과 조립 예시 3종, 총 12개 GLB가 등록돼 있습니다. 실제 생성에서는 점자블록 원본을 그대로 쓰고, 연석·경사판·노면 표시는 도로 폭과 지형에 맞는 가변 형상으로 만듭니다.</p><div class="grid three">{figure('images/asset-alley.jpg','작은 길 접속 · 조립 예시','형상 원칙을 확인하는 평지 예시입니다. 실제 지도 한 곳의 재현은 아닙니다.')}{figure('images/asset-t.jpg','보도 있는 T자 · 조립 예시','양쪽 보행 연결과 모퉁이, 횡단 개구를 함께 확인합니다.')}{figure('images/asset-cross.jpg','다차로 사거리 · 조립 예시','회전 방향별 8개 개구를 검사했습니다. 고정 예시 GLB의 1.5cm 턱은 자동 생성 경사판과 구분합니다.')}</div><div class="grid rules" style="margin-top:1.25rem"><article class="card rule"><h3>도로 공간부터 확정</h3><p>실제 정보와 수동 편집을 우선합니다. 분리된 상·하행 중심선에 왕복 폭을 두 번 적용하지 않습니다.</p></article><article class="card rule"><h3>폭이 달라지면 점진 연결</h3><p>직진하는 두 구간의 폭 차이는 넓은 구간 안에서 서서히 연결합니다. 모퉁이는 폭과 각도를 함께 봅니다.</p></article><article class="card rule"><h3>횡단 시설은 한 묶음</h3><p>횡단보도와 양쪽 경사판·점자블록 전체가 들어갈 때 배치합니다. 부분 누락을 성공으로 처리하지 않습니다.</p></article><article class="card rule"><h3>최종 표면에 맞추기</h3><p>차선은 완성된 노면에 투영합니다. 경고띠는 실제 평탄면에 놓고 바닥 네 모서리까지 확인합니다.</p></article></div><details><summary>합성 10등급 조합 검사 보기</summary><p>이 그림은 코드 검사용 합성 입력입니다. 실제 10개 지역의 로드뷰나 공개 배치 확인이 아닙니다.</p>{figure('images/grade-matrix.png','합성 도로 등급 조합','1–1부터 4–4까지의 조합. 실제 공개 장면의 확인 조합은 1–2, 1–3, 2–3입니다.')}</details></section>
<section id="checks"><p class="eyebrow">05 / 확인 근거</p><h2>계획과 실제 결과를 대조했습니다</h2><div class="table-wrap"><table><thead><tr><th scope="col">확인 항목</th><th scope="col">결과</th><th scope="col">무엇을 뜻하나요</th></tr></thead><tbody><tr><th scope="row">공개 실제 생성</th><td>교차로 5 · 횡단부 2 · 경사판 4 · 점자 4</td><td>저장된 실제 원자료로 전체 재생성</td></tr><tr><th scope="row">노면 접합</th><td>외곽 43구간 / 내부 공유점 209개</td><td>높이 차가 부동소수점 오차 수준</td></tr><tr><th scope="row">경사판 옆 보도</th><td>24개 표본쌍 · 최대 높이 차 0.013mm</td><td>평탄부 양옆의 실제 삼각면 연결 확인</td></tr><tr><th scope="row">점자블록 접지</th><td>바닥 20점 · 최대 차 0.021mm</td><td>네 모서리와 중심을 완성 표면과 대조</td></tr><tr><th scope="row">보도면 단면</th><td>8개 단면 · 최소 1.5m</td><td>장애물까지 모두 뺀 최종 유효 통로폭은 아님</td></tr><tr><th scope="row">회귀 검사</th><td>도로 40 · 교차로 11 · GLB 12종</td><td>합성 조합·회전 개구·브라우저 생성 묶음 검사 포함</td></tr></tbody></table></div><p class="caption-note">소스 7a0323e · <a href="https://github.com/bacbaqui-web/magamiscoming/actions/runs/44940921979">공개 생성기 배포 기록 ↗</a> · 독립 검토자 generated_junction_audit의 보고서를 주 에이전트가 다시 확인했습니다.</p></section>
<section id="limits"><p class="eyebrow">06 / 남은 문제</p><h2>완료 범위를 넘어선 부분은 남겨 둡니다</h2><div class="grid"><article class="card"><span class="tag old">외부 조회</span><h3>멀리 있는 건물 일부를 불러오지 못했습니다</h3><p>공개 화면의 VWorld 연결 실패 안내는 남아 있습니다. 이번 확인은 저장된 실제 자료의 전체 재생성이며, 새 주소의 외부 조회까지 해결됐다는 뜻은 아닙니다.</p></article><article class="card"><span class="tag old">건물 위치</span><h3>제외 1동과 과도한 이동은 별도 문제입니다</h3><p>도봉로198 원본 805동 중 도로 조정 후 804동을 유지하고 1동을 제외했습니다. 7.51㎡ 건물은 이동 여유가 없고 절단 후 약 1.04㎡만 남았습니다.</p><p>시야 후보 96동 중 실제 생성은 45동입니다. 별도 도봉로188 검사에서 825동을 모두 유지했어도 작은 건물의 약 30m 이동은 원위치 정확성의 한계입니다.</p></article><article class="card"><span class="tag">검사 범위</span><h3>모든 교차로를 확인한 것은 아닙니다</h3><p>실제 모든 등급 조합·급경사·입체교차·야간을 확인하지 않았습니다. 시설 전체 부피를 제외한 통로폭도 미확인입니다.</p></article><article class="card"><span class="tag good">사용 시 적용</span><h3>기존 동네는 재생성할 때 바뀝니다</h3><p>수동 지정 정보는 유지합니다. 이번 검사 사본은 해당 브라우저에 저장돼 있으므로 다른 기기에서 같은 ID를 열어도 자동으로 공유되지는 않습니다.</p><a href="https://magamiscom.ing/neighborhood/">우리동네 열기 ↗</a></article></div></section>
<section id="archive"><p class="eyebrow">07 / 사진 기록</p><h2>200장, 25개 관찰 묶음</h2><p class="section-intro">같은 장소의 회전 시점이 포함됩니다. 묶음을 펼쳐 사진 번호·관찰 내용·출처를 확인하세요. 정확한 촬영 위치 링크가 아닌 해당 일대의 검색 링크입니다.</p>'''
